import java.util.Scanner;

public class easy {
    static class State {
        boolean inside;
        StringBuilder current = new StringBuilder();
        int max;
        int words;
    }

    static void process(State st, char c) {
        if (c == '(') {
            st.inside = true;
            if (st.current.length() > st.max) st.max = st.current.length();
            st.current.setLength(0);
        } else if (c == ')') {
            st.inside = false;
            if (st.current.length() > 0) {
                st.words++;
                st.current.setLength(0);
            }
        } else if (Character.isLetter(c)) {
            st.current.append(c);
        } else if (c == '_') {
            if (st.inside) {
                if (st.current.length() > 0) {
                    st.words++;
                    st.current.setLength(0);
                }
            } else {
                if (st.current.length() > st.max) st.max = st.current.length();
                st.current.setLength(0);
            }
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int how = in.nextInt();
        in.nextLine();
        String s = in.nextLine();
        State st = new State();
        for (char c : s.toCharArray()) {
            process(st, c);
        }
        if (st.current.length() > st.max) st.max = st.current.length();
        System.out.println(st.max + " " + st.words);
    }
}
